public class OnlineStockSpanTest {

    @Test
    public void next_WhenPriceIsZero_ReturnsOne() {
        // given
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        int price = 0;

        // when
        int result = stockSpan.next(price);

        // then
        assertEquals(1, result);
    }

    @Test
    public void next_WhenPriceIsPositive_ReturnsOne() {
        // given
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        int price = 10;

        // when
        int result = stockSpan.next(price);

        // then
        assertEquals(1, result);
    }

    @Test
    public void next_WhenPriceIsNegative_ReturnsOne() {
        // given
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        int price = -10;

        // when
        int result = stockSpan.next(price);

        // then
        assertEquals(1, result);
    }

    @Test
    public void next_WhenMultiplePricesAreGiven_ReturnsCorrectSpans() {
        // given
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        int[] prices = {10, 7, 5, 8, 11, 9};

        // when
        for (int price : prices) {
            stockSpan.next(price);
        }

        // then
        int[] result = stockSpan.calculateSpans(prices);
        assertEquals(5, result[0]);
    }

    @Test
    public void next_WhenOnlyOnePriceIsGiven_ReturnsCorrectSpan() {
        // given
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        int[] prices = {10};

        // when
        for (int price : prices) {
            stockSpan.next(price);
        }

        // then
        int[] result = stockSpan.calculateSpans(prices);
        assertEquals(1, result[0]);
    }

    @Test
    public void next_WhenMultiplePricesAreGivenAndPreviousPriceIsZero_ReturnsCorrectSpan() {
        // given
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        int[] prices = {10, 7, 5};

        // when
        for (int price : prices) {
            stockSpan.next(price);
        }

        // then
        int[] result = stockSpan.calculateSpans(prices);
        assertEquals(4, result[0]);
    }

    @Test
    public void calculateSpans_WhenOnlyOnePriceIsGiven_ReturnsCorrectSpan() {
        // given
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        int[] prices = {10};

        // when
        int[] result = stockSpan.calculateSpans(prices);

        // then
        assertEquals(1, result[0]);
    }

    @Test
    public void calculateSpans_WhenMultiplePricesAreGiven_ReturnsCorrectSpans() {
        // given
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        int[] prices = {10, 7, 5, 8, 11, 9};

        // when
        for (int price : prices) {
            stockSpan.next(price);
        }

        // then
        int[] result = stockSpan.calculateSpans(prices);
        assertEquals(5, result[0]);
    }
}
